    100000             25
  10000000            262
1410065408        5737822 Clearly seeing this as incorrect, I tried putting a #pragma above the for loop in the is_prime() function, but I got compiler error saying error: "invalid branch to/from OpenMP structured block". I realize this error is coming from the thread potentially entering the if statement and returning 0 in the middle of the parallel operations. The thread gets terminated prematurely and the entire operation comes apart. I feel like its most appropriate to put the #pragma inside the function call, as it can cut the run time down by v/4 for each call to the function. However, I do not know the proper syntax to do this. If someone can please help me out I'd greatly appreciate it. Thanks

answers.body:
user3666197 gives you an example of how to do this by hand. That is fine for understanding, but you don't need to do it yourself - instead you should use the abstraction OpenMP provides - which is a reduction. A reduction will give each thread a private variable and after the parallel computation, those are added together to the original variable. A correct example without the intermediate output is simply: int prime_count = 1;

#pragma omp parallel for reduction(+:prime_count)
for (uint32_t i = 3; i < END; i += 2) {
    if (is_prime(i)) {
        prime_count++;
    }
}
printf("%12d\t%12d\n", 0, prime_count); To reproduce the intermediate output in parallel. I would rather have all threads work on a bracket and then one reports the aggregate result. This is still easily achievable with a reduction and gives you a correct summarized information of how many primes are in each chunk: int prime_count = 1;

#pragma omp parallel
for (uint32_t bracket = 10; bracket <= END; bracket *= 10)
{
    uint32_t start = bracket / 10;
    if (start == 1) start = 3;
    else start++;
    #pragma omp for reduction(+:prime_count)
    for (uint32_t i = start; i < bracket; i += 2) {
        if (is_prime(i)) {
            prime_count++;
        }
    }
    #pragma omp single
    printf("%12d\t%12d %p\n", bracket, prime_count);
}
printf("%12d\t%12d\n", 0, prime_count); I split the for and parallel because it can be costly to reopen parallel regions again and again.

This method is 5 times faster than the corrected OP. It first makes an array of primes up to the square root, single threaded. Then the multiple threads only read from that array. /* Prime numbers by trial division, with parallel 2nd step */
/* Trick is to make sure the SQR array has top prime > SQR to make the for loop work until the end / the last p[i]
   Lowest MAX is 4 */
/* Timing: 0.13s for up to 10M (4 cores, turbo boost 3GHz) */

/* single threaded, array filling step only: timing:
./a.out 1000000000000
top: 78497 1000003 1000006000009
-> 0.04s for 78K primes up to 1M, ready for 1T (would take hours/years) 
-> does not matter overall
*/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <omp.h>

/* Fill p[] with primes up to 'max', and one more */
int
primearray(int max, int p[]) {

    p[0] = 3;
    int top = 0, n, i;

    for (n = 5;; n += 2)
        for (i = 0;; i++)

            if (n % p[i] == 0)
                break;
            else
                if (p[i]*p[i] > n) {

                    p[++top] = n;
                    if (n > max)
                        return top;          // return WITH last n
                    break;
                }
}
/* Use primes in p[] to check up to 'max' */
/* "5" is p[1] is the 3rd prime, so start count from 2 */
int
primecount_omp(long max, int p[]) {

    int n, i, sum = 2;

    #pragma omp parallel for private(i) schedule(guided) reduction(+:sum)

    for (n = 5; n <= max; n += 2)
        for (i = 0;; i++)

            if (n % p[i] == 0)
                break;
            else
                if (p[i]*p[i] > n) {
                    sum++;
                    break;
                }
    return sum;
}
/* Call primearray() with SQR and then primecount_omp() with MAX */
