    for (int j=0;j<pno;j++)
            {
            fprintf(fill,"%.16f\t%.16f\t%.16f\t%.16f\t%.16f\t%.16f\t%.16f\n", x[j][0],x[j][1],x[j][2],v[j][0],v[j][1],v[j][2],
                calculate_erg(x[j],v[j],mt_c));
            }
    fclose(fill);

}
