answers.body:
You can implement the scheduling yourself.  Here is an example using the equivalent of schedule(static) with GCC's builtin 128-bit integers. #pragma omp parallel
{
    __int128 start = omp_get_thread_num()*N/omp_get_num_threads();
    __int128 finish = (omp_get_thread_num()+1)*N/omp_get_num_threads();
    for(__int128 i=start; i<finish; i++) foo(i);
} If you want the equivalent of schedule(dynamic) you can do __int128 cnt = 0;
#pragma omp parallel
for(__int128 i=0;;) {
    #pragma omp atomic capture
    i = cnt++;
    if(i>=N) break;
    foo(i);                                    
}

