You can manually do the reduction like this #pragma omp parallel
{
  arma::vec t = arma::zeros<arma::vec>(M);
  #pragma omp for nowait
  for (int i = 0; i < N; ++i) t += arma::ones<arma::vec>(v.n_rows);
  #pragma omp critical
  v += t;
} That works with Clang. This could help you figure out how to define the initializer-expr For example this works with GCC 7 #pragma omp declare reduction( + : arma::vec : omp_out += omp_in ) \
initializer( omp_priv = arma::zeros<arma::vec>(omp_orig.n_rows)) However with Clang 5.0 the code hangs so I'm not sure what Clang's problem is. I tried other initializer-expr variations but none of them got Clang to work. I installed clang7 and the OP's code works fine. In general I think it's a better idea to be explicitly set the vector to zero like this initializer( omp_priv = arma::zeros<arma::vec>(omp_orig.n_rows)) rather than implicitly like this initializer(omp_priv = omp_orig) because the implicit case assumes the constructor initializes to zero.

Since the original question also asked about Eigen, here is a self-contained example working with gcc 5, 6, 7, 8 and clang 6. It segfaults with clang 5, likely a bug on clang 5 side. This is essentially the same solution as proposed by Z boson. #include <Eigen/Core>
#include <iostream>
using namespace Eigen;

typedef VectorXd vec;

#pragma omp declare reduction( + : vec : omp_out += omp_in ) \
  initializer( omp_priv = vec::Zero(omp_orig.size()) )

int main() {
    int N = 10000;
    int M = 100;
    vec v = vec::LinSpaced(M,0,M-1);

    #pragma omp parallel for reduction(+:v)
    for (int i = 0; i < N; ++i){
        v += vec::Ones(v.size());
    }

    std::cout << v.transpose() << std::endl;
    return 0;
}

