answers.body:
If you only want the reduction in the function you can use static storage.  From 2.14.1.2 of the OpenMP 4.0.0 specification Variables with static storage duration that are declared in called routines in the region are shared. #include <stdio.h>

void do_stuff(int arg1, int arg2)
{
    static int sum = 0;
    #pragma omp for reduction(+:sum)
    for(int i=0; i<arg1;i++) sum += arg2;
    printf("sum %d\n", sum);
}

int main(void) {
    const int time_limit = 10;
    int x[time_limit]; for(int i=0; i<time_limit; i++) x[i] = i;
    #pragma omp parallel
    {
        for(int j=0;j<time_limit;j++) do_stuff(10,x[j]);
    }
}

